-- СГЕНЕРИРОВАНО scripts/make-seed.mjs из src/data.js — руками не править.
-- Запуск: Supabase → SQL Editor → вставить → Run (после schema.sql).
-- Туров, которых больше нет в data.js, скрываются (published = false), а не удаляются,
-- чтобы не сломать старые заявки, которые на них ссылаются.

insert into public.tours
  (id, category, type, title, place, duration, price, rating, reviews, badge, langs, agency_name, source_url, images,
   lat, lng, free_cancel, group_size, meeting, description, highlights, includes, i18n, published, sort)
values
  ('walking', 'tours', 'Экскурсия', 'Пешая экскурсия по Ошу', 'Центр Оша', '2 часа', 17.44, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/osh-city-walking-tour/', array['https://bestofosh.com/wp-content/uploads/2019/05/Lenin-statue-in-Osh-e1559745162625.webp']::text[], 40.531, 72.795, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Главная улица, зелёные парки и история Оша: досоветская, советская и современная, а также культура и известные люди города.', array['Каждый день', 'Старт в 9:00 и 16:00', 'Гид — местный житель']::text[], '{}'::text[], '{"en":{"title":"Osh city walking tour","type":"Walking tour","place":"Central Osh","meeting":"Meeting details are arranged with Best of Osh","description":"Walk the central street and green parks and hear about Osh''s pre-Soviet, Soviet and modern history, culture and famous people.","highlights":["Every day","Starts at 9:00 and 16:00","Local guide"]}}'::jsonb, true, 10),
  ('bread', 'practices', 'Мастер-класс', 'Хлеб в тандыре: мастер-класс', 'Тандырная мастерская', '2 часа', 23.26, null, 0, 'Практика', 'EN', 'Best of Osh', 'https://bestofosh.com/osh-bread-baking/', array['https://bestofosh.com/wp-content/uploads/2025/03/bread-baking-tour-osh-1.webp']::text[], 40.526, 72.8, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Пекарские традиции Оша: мастерская тандыров и местная пекарня. Сами формуете и печёте лепёшку и едите её за местным завтраком.', array['Каждый день', 'Старт в 9:00', 'Завтрак со своим хлебом']::text[], '{}'::text[], '{"en":{"title":"Bread-baking tour","type":"Workshop","place":"Tandoor workshop","meeting":"Meeting details are arranged with Best of Osh","description":"Discover Osh''s baking traditions: a tandoor workshop and a local bakery. Shape and bake your own bread and enjoy it with a local breakfast.","highlights":["Every day","Starts at 9:00","Breakfast with your own bread"],"badge":"Hands-on"}}'::jsonb, true, 20),
  ('plov', 'food', 'Мастер-класс', 'Плов с нуля: кулинарный мастер-класс', 'Дом местной семьи', '4 часа', 40.7, null, 0, 'Практика', 'EN', 'Best of Osh', 'https://bestofosh.com/plov-cooking-tour/', array['https://bestofosh.com/wp-content/uploads/2025/03/plov-cooking-tour-osh.webp']::text[], 40.52, 72.81, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Главное блюдо Центральной Азии с нуля: выбираете продукты, режете и готовите плов в традиционной обстановке.', array['Каждый день', 'Старт в 15:00', 'Покупка продуктов на базаре']::text[], '{}'::text[], '{"en":{"title":"Plov Cooking 101","type":"Cooking class","place":"Local family home","meeting":"Meeting details are arranged with Best of Osh","description":"Cook Central Asia''s iconic dish from scratch: pick your groceries, chop the ingredients and cook plov in a traditional setting.","highlights":["Every day","Starts at 15:00","Grocery shopping at the bazaar"],"badge":"Hands-on"}}'::jsonb, true, 30),
  ('sulaiman', 'tours', 'Экскурсия', 'Экскурсия на Сулайман-Тоо', 'Сулайман-Тоо', '2 часа', 23.26, null, 0, 'Хит', 'EN', 'Best of Osh', 'https://bestofosh.com/sulaiman-too-tour/', array['https://bestofosh.com/wp-content/uploads/2019/05/Sulaiman-Too-House-of-Babur-1024x768.jpg']::text[], 40.5275, 72.7985, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Главная достопримечательность Оша — гора Сулайман-Тоо: древняя и средневековая история, местные верования и панорама города.', array['Вторник–воскресенье', 'Старт в 9:00 и 15:00', 'Дом Бабура на вершине']::text[], '{}'::text[], '{"en":{"title":"Sulaiman-Too tour","type":"Tour","place":"Sulaiman-Too","meeting":"Meeting details are arranged with Best of Osh","description":"Visit Osh''s main sight, Sulaiman-Too Mountain: ancient and medieval history, local beliefs and panoramic views.","highlights":["Tuesday to Sunday","Starts at 9:00 and 15:00","Babur''s House at the top"],"badge":"Top pick"}}'::jsonb, true, 40),
  ('food-tour', 'food', 'Гастротур', 'Гастротур по Ошу', 'Кафе и чайханы Оша', '3 часа', 34.88, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/food-tour/', array['https://bestofosh.com/wp-content/uploads/2025/03/osh-food-tour.webp']::text[], 40.5233, 72.7969, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Ош — гастрономическая столица Кыргызстана. Лучшие кафе, рестораны и чайханы и философия местной кухни.', array['Вт, ср, чт, сб, вс', 'Старт в 11:00', 'Несколько заведений за тур']::text[], '{}'::text[], '{"en":{"title":"Osh food tour","type":"Food tour","place":"Cafés and teahouses of Osh","meeting":"Meeting details are arranged with Best of Osh","description":"Discover the food capital of Kyrgyzstan through its cuisine and cooking philosophy at the best cafés, restaurants and teahouses.","highlights":["Tue, Wed, Thu, Sat, Sun","Starts at 11:00","Several places in one tour"]}}'::jsonb, true, 50),
  ('pamir', 'trips', 'Поездка из Оша', 'Памирский тракт', 'Памир', '8 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/pamir-highway-tour/', array['https://bestofosh.com/wp-content/uploads/2025/03/Pamir-highway-tours.webp']::text[], 38.17, 73.96, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Путешествие по «крыше мира»: нетронутая природа, самобытные культуры и эпичные виды. Апрель–ноябрь, маршрут можно менять.', array['Апрель–ноябрь', 'Большие высоты', 'Маршрут под вас']::text[], '{}'::text[], '{"en":{"title":"Pamir Highway tour","type":"Trip from Osh","place":"Pamir","meeting":"Meeting details are arranged with Best of Osh","description":"An odyssey across the Roof of the World: pristine nature, authentic cultures and epic scenery. April–November, customizable.","highlights":["April–November","High altitudes","Customizable route"]}}'::jsonb, true, 60),
  ('sary-chelek', 'trips', 'Поездка из Оша', 'Сары-Челек: природа во всей красе', 'Озеро Сары-Челек', '3 дня', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/tour-to-sary-chelek-2/', array['https://bestofosh.com/wp-content/uploads/2025/03/Sary-Chelek.webp']::text[], 41.87, 71.96, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Завораживающее горное озеро, заповедная флора и фауна и походы по нетронутой природе.', array['Горное озеро', 'Заповедник', 'Лёгкие походы']::text[], '{}'::text[], '{"en":{"title":"Sary-Chelek: nature at its best","type":"Trip from Osh","place":"Sary-Chelek Lake","meeting":"Meeting details are arranged with Best of Osh","description":"A mesmerizing alpine lake, protected flora and fauna and hikes through pristine nature.","highlights":["Alpine lake","Nature reserve","Easy hikes"]}}'::jsonb, true, 70),
  ('arslanbob', 'trips', 'Поездка из Оша', 'Арсланбоб: легенды леса', 'Арсланбоб', '2 дня', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/tour-to-arslanbob/', array['https://bestofosh.com/wp-content/uploads/2025/03/Tours-Arslanbob-e1741240149937.webp']::text[], 41.33, 72.94, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Крупнейший в мире ореховый лес, панорамы, водопады и пещеры и необычное село со своей культурой.', array['Ореховый лес', 'Водопады и пещеры', 'Сельская жизнь']::text[], '{}'::text[], '{"en":{"title":"Arslanbob: forest legends","type":"Trip from Osh","place":"Arslanbob","meeting":"Meeting details are arranged with Best of Osh","description":"The world''s largest walnut forest, panoramic views, waterfalls and caves, and a village with its own culture.","highlights":["Walnut forest","Waterfalls and caves","Village life"]}}'::jsonb, true, 80),
  ('issyk-kul', 'trips', 'Поездка', 'Лучшее на Иссык-Куле', 'Иссык-Куль', '5 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/best-of-issyk-kul/', array['https://bestofosh.com/wp-content/uploads/2025/03/tour-to-issykul-1.webp']::text[], 42.45, 77.2, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Пять дней вокруг жемчужины Кыргызстана: природа, культура, кухня, национальные напитки и мёд.', array['5 дней', 'Природа и кухня', 'Напитки и мёд']::text[], '{}'::text[], '{"en":{"title":"Best of Issyk-Kul","type":"Trip","place":"Issyk-Kul","meeting":"Meeting details are arranged with Best of Osh","description":"Five days around the pearl of Kyrgyzstan: nature, culture and food, national drinks and honey.","highlights":["5 days","Nature and food","Drinks and honey"]}}'::jsonb, true, 90),
  ('lenin-hike', 'trekking', 'Треккинг', 'Поход вокруг пика Ленина (4 дня)', 'Алайская долина', '4 дня', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/hike-around-the-lenin-peak/', array['https://bestofosh.com/wp-content/uploads/2024/06/Lenin-Peak-Hike.webp']::text[], 39.53, 72.87, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Лучшее в Алайских горах: захватывающие виды и время с настоящими кочевниками.', array['Пик Ленина', 'Кочевники', 'Сложность выше средней']::text[], '{}'::text[], '{"en":{"title":"Hike around Lenin Peak (4 days)","type":"Trek","place":"Alay Valley","meeting":"Meeting details are arranged with Best of Osh","description":"The best of the Alay Mountains: breathtaking scenery and time with real nomads.","highlights":["Lenin Peak","Nomads","Medium to hard"]}}'::jsonb, true, 100),
  ('alay-5', 'trekking', 'Треккинг', 'Высоты Алая (5 дней)', 'Алайские горы', '5 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/heights-of-alay-trek/', array['https://bestofosh.com/wp-content/uploads/2024/06/Hike-Tulpar-Kul.webp']::text[], 39.6, 72.9, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Самый популярный треккинг: эпичные Алайские горы, нетронутая природа и кочевая культура. 3 дня пешком.', array['Середина июня — начало сентября', '3 дня пешком', 'Кочевая культура']::text[], '{}'::text[], '{"en":{"title":"Heights of Alay (5 days)","type":"Trek","place":"Alay Mountains","meeting":"Meeting details are arranged with Best of Osh","description":"The bestselling trek: epic Alay mountains, pristine nature and nomadic culture. 3 days of hiking.","highlights":["Mid-June to early September","3 days of hiking","Nomadic culture"]}}'::jsonb, true, 110),
  ('alay-7', 'trekking', 'Треккинг', 'Высоты Алая (7 дней)', 'Алайские горы', '7 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/7-days-trek-from-osh-city-heights-of-alay/', array['https://bestofosh.com/wp-content/uploads/2024/06/Hike-Lenin-Peak.webp']::text[], 39.6, 72.9, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Величественная природа юга: реки, пастбища и озёра, сельская и кочевая жизнь.', array['Реки и озёра', 'Пастбища', 'Сельская жизнь']::text[], '{}'::text[], '{"en":{"title":"Heights of Alay (7 days)","type":"Trek","place":"Alay Mountains","meeting":"Meeting details are arranged with Best of Osh","description":"The majestic nature of the south: rivers, pastures and lakes, rural and nomadic life.","highlights":["Rivers and lakes","Pastures","Rural life"]}}'::jsonb, true, 120),
  ('alay-9', 'trekking', 'Треккинг', 'Высоты Алая (9 дней)', 'Алайские горы', '9 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/heights-of-alay-9-days/', array['https://bestofosh.com/wp-content/uploads/2024/06/Hiking-around-Lenin-Peak.webp']::text[], 39.6, 72.9, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Длинная версия популярного треккинга по Алайским горам: природа и кочевая культура.', array['9 дней', 'Алайские горы', 'Кочевая культура']::text[], '{}'::text[], '{"en":{"title":"Heights of Alay (9 days)","type":"Trek","place":"Alay Mountains","meeting":"Meeting details are arranged with Best of Osh","description":"The long version of the bestselling Alay trek: pristine nature and nomadic culture.","highlights":["9 days","Alay Mountains","Nomadic culture"]}}'::jsonb, true, 130),
  ('yukhin-4', 'trekking', 'Восхождение', 'Пик Юхина за 4 дня', 'Пик Юхина', '4 дня', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/yukhin-peak-4-days/', array['https://bestofosh.com/wp-content/uploads/2025/06/AKXN1612.webp']::text[], 39.45, 72.85, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Восхождение на один из любимых пиков для акклиматизации: нетронутая природа, сельская и кочевая жизнь.', array['Акклиматизационный пик', 'Средне — сложно', 'Кочевая жизнь']::text[], '{}'::text[], '{"en":{"title":"Yukhin Peak in 4 days","type":"Climb","place":"Yukhin Peak","meeting":"Meeting details are arranged with Best of Osh","description":"Climb one of the favourite acclimatization peaks: pristine nature, rural and nomadic life.","highlights":["Acclimatization peak","Moderate to challenging","Nomadic life"]}}'::jsonb, true, 140),
  ('yukhin-8', 'trekking', 'Восхождение', 'Пик Юхина за 8 дней', 'Пик Юхина', '8 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/8-days-yukhin-peak/', array['https://bestofosh.com/wp-content/uploads/2025/06/IMG-20231106-WA00091.webp']::text[], 39.45, 72.85, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Длинная программа восхождения на пик Юхина с акклиматизацией. Середина июня — начало сентября.', array['8 дней', 'Сложно', 'Июнь — сентябрь']::text[], '{}'::text[], '{"en":{"title":"Yukhin Peak in 8 days","type":"Climb","place":"Yukhin Peak","meeting":"Meeting details are arranged with Best of Osh","description":"A longer Yukhin Peak climb with acclimatization. Mid-June to early September.","highlights":["8 days","Challenging","June to September"]}}'::jsonb, true, 150),
  ('horse-4', 'trekking', 'Конный тур', 'Конный поход по Алаю (4 дня)', 'Алайские горы', '4 дня', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/horse-trekking-from-osh/', array['https://bestofosh.com/wp-content/uploads/2025/12/Horse-riding-tour-osh.webp']::text[], 39.65, 73, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Четыре дня верхом по Алайским горам.', array['Верхом', 'Алайские горы', '4 дня']::text[], '{}'::text[], '{"en":{"title":"4-day horse trek in Alay","type":"Horse trek","place":"Alay Mountains","meeting":"Meeting details are arranged with Best of Osh","description":"Four days on horseback in the Alay Mountains.","highlights":["On horseback","Alay Mountains","4 days"]}}'::jsonb, true, 160),
  ('horse-5', 'trekking', 'Конный тур', 'Конный поход по Алаю (5 дней)', 'Алайские горы', '5 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/5-day-horse-riding-trek-from-osh-kyrgyzstan/', array['https://bestofosh.com/wp-content/uploads/2025/12/horse-riding-tours-kyrgyzstan.webp']::text[], 39.65, 73, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Пять дней верхом по Алаю. Подходит новичкам с базовым опытом езды.', array['Верхом', 'Для новичков с опытом', '5 дней']::text[], '{}'::text[], '{"en":{"title":"5-day horse trek in Alay","type":"Horse trek","place":"Alay Mountains","meeting":"Meeting details are arranged with Best of Osh","description":"Five days riding in Alay. Suitable for beginners with basic riding experience.","highlights":["On horseback","Beginners with some experience","5 days"]}}'::jsonb, true, 170),
  ('horse-9', 'trekking', 'Конный тур', 'Конный поход по Алаю (9 дней)', 'Алайские горы', '9 дней', null, null, 0, null, 'EN', 'Best of Osh', 'https://bestofosh.com/9-day-horse-riding-from-osh-city-in-the-alay-mountains/', array['https://bestofosh.com/wp-content/uploads/2025/12/Horse-riding-tours-from-Osh-city.webp']::text[], 39.65, 73, false, null, 'Детали встречи — по согласованию с Best of Osh', 'Девять дней верхом по Алайским горам. Средне — сложно, нужен базовый опыт езды.', array['Верхом', '9 дней', 'Нужен опыт езды']::text[], '{}'::text[], '{"en":{"title":"9-day horse trek in Alay","type":"Horse trek","place":"Alay Mountains","meeting":"Meeting details are arranged with Best of Osh","description":"Nine days riding in the Alay Mountains. Moderate to challenging; basic riding experience needed.","highlights":["On horseback","9 days","Riding experience needed"]}}'::jsonb, true, 180)
on conflict (id) do update set
  category = excluded.category, type = excluded.type, title = excluded.title, place = excluded.place,
  duration = excluded.duration, price = excluded.price, rating = excluded.rating, reviews = excluded.reviews,
  badge = excluded.badge, langs = excluded.langs, agency_name = excluded.agency_name, source_url = excluded.source_url,
  images = excluded.images, lat = excluded.lat, lng = excluded.lng,
  free_cancel = excluded.free_cancel, group_size = excluded.group_size, meeting = excluded.meeting,
  description = excluded.description, highlights = excluded.highlights, includes = excluded.includes,
  i18n = excluded.i18n, published = excluded.published, sort = excluded.sort;

update public.tours set published = false
where agency_id is null and id not in ('walking', 'bread', 'plov', 'sulaiman', 'food-tour', 'pamir', 'sary-chelek', 'arslanbob', 'issyk-kul', 'lenin-hike', 'alay-5', 'alay-7', 'alay-9', 'yukhin-4', 'yukhin-8', 'horse-4', 'horse-5', 'horse-9');

insert into public.facts
  (id, title, emoji, short, image, tag, body, points, link_label, link_tab, exp_id, i18n, published, sort)
values
  ('older-than-rome', 'Город старше Рима', '🏛️', 'Археологические находки на склонах Сулайман-Тоо подтверждают свыше 3000 лет непрерывной городской истории.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200&q=85', 'История', array['Ош считается одним из древнейших городов Центральной Азии: на склонах и у подножия Сулайман-Тоо найдены следы поселений эпохи бронзы — это более трёх тысяч лет непрерывной городской жизни.', 'Город вырос на пересечении ферганских торговых путей: здесь останавливались караваны, шедшие из Кашгара в Самарканд, и именно торговля сформировала характер ошских базаров, которые работают на тех же местах до сих пор.']::text[], array['Сулайман-Тоо — объект Всемирного наследия ЮНЕСКО (с 2009 года)', 'На горе более 100 мест наскальных рисунков и культовых площадок', 'Музей внутри горы устроен в естественной пещере']::text[], 'Посмотреть туры по Сулайман-Тоо', 'tours', 'sulaiman', '{"en":{"title":"A city older than Rome","short":"Archaeological finds on the slopes of Sulaiman-Too point to more than 3,000 years of continuous urban history.","tag":"History","body":["Osh is considered one of the oldest cities in Central Asia: Bronze Age settlement traces have been found on the slopes and at the foot of Sulaiman-Too — more than three thousand years of continuous city life.","The city grew at a crossroads of Fergana trade routes: caravans travelling from Kashgar to Samarkand stopped here, and trade shaped the character of the Osh bazaars, which still operate in the same places today."],"points":["Sulaiman-Too has been a UNESCO World Heritage Site since 2009","The mountain has over 100 sites with petroglyphs and places of worship","A museum inside the mountain occupies a natural cave"],"linkLabel":"See Sulaiman-Too tours"}}'::jsonb, true, 10),
  ('devzira', 'Легендарный рис Девзира', '🍚', 'Главный сорт для ошского плова выращивают на местных полях Ферганской долины.', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1200&q=85', 'Кухня', array['Девзира — розовато-коричневый рис с плотным зерном, который выращивают в Ферганской долине. Именно он даёт ошскому плову характерную рассыпчатость: зерно впитывает бульон, но не разваривается.', 'На базаре Девзиру узнают по мучному налёту и продольной бороздке: продавцы предлагают потереть зерно в ладонях — настоящий рис слегка скрипит и оставляет светлую пыль.']::text[], array['Рис вызревает дольше обычного — отсюда цена выше', 'Перед готовкой его промывают и замачивают в тёплой солёной воде', 'Ошский плов готовят на курдючном сале, морковь кладут двумя слоями']::text[], 'Мастер-класс по плову', 'tours', 'plov', '{"en":{"title":"The legendary Devzira rice","short":"The key rice for Osh plov is grown in local fields of the Fergana Valley.","tag":"Cuisine","body":["Devzira is a pinkish-brown, firm-grained rice grown in the Fergana Valley. It gives Osh plov its signature fluffiness: the grain soaks up the broth without turning mushy.","At the bazaar you can spot Devzira by its powdery coating and a groove along the grain. Sellers invite you to rub it between your palms — real Devzira squeaks a little and leaves a light dust."],"points":["It ripens longer than ordinary rice — hence the higher price","Before cooking it is rinsed and soaked in warm salted water","Osh plov is cooked in tail fat, with carrots laid in two layers"],"linkLabel":"Plov cooking class"}}'::jsonb, true, 20),
  ('jaima-bazaar', 'Базар, которому тысячи лет', '🧺', 'Базар Джайма тянется вдоль реки Ак-Буура и остаётся одним из крупнейших рынков Центральной Азии.', 'https://images.unsplash.com/photo-1567696911980-2eed69a46042?w=1200&q=85', 'Традиции', array['Джайма — не туристическая декорация, а живой рынок, который работает на берегу Ак-Бууры много столетий. Ряды растянуты почти на километр: специи, сухофрукты, ножи, тюбетейки, ткани, конская упряжь.', 'Лучшее время — утро до 11:00: ещё прохладно, товар свежий, а торговцы охотнее угощают и рассказывают. Торг здесь — часть этикета, но вести его принято спокойно и с улыбкой.']::text[], array['Ножи ручной ковки — один из главных местных сувениров', 'Курут, урюк и грецкий орех продают на вес, пробовать можно бесплатно', 'Оплата чаще наличными в сомах — карту принимают не везде']::text[], 'Гастротур по Ошу', 'tours', 'food-tour', '{"en":{"title":"A bazaar thousands of years old","short":"Jayma Bazaar stretches along the Ak-Buura river and remains one of the largest markets in Central Asia.","tag":"Traditions","body":["Jayma isn''t a tourist set — it''s a living market that has traded on the banks of the Ak-Buura for centuries. The rows run for almost a kilometre: spices, dried fruit, knives, skullcaps, fabrics, horse tack.","The best time is the morning before 11:00: it''s still cool, the goods are fresh, and traders are happier to offer a taste and chat. Bargaining is part of the etiquette, but it''s done calmly and with a smile."],"points":["Hand-forged knives are one of the top local souvenirs","Kurut, dried apricots and walnuts are sold by weight — tasting is free","Cash in som is usual — cards aren''t accepted everywhere"],"linkLabel":"Osh food tour"}}'::jsonb, true, 30),
  ('silk-road-crossroads', 'Перекрёсток Шёлкового пути', '🐪', 'Через Ош проходила северная ветка Великого шёлкового пути в Ферганскую долину.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?w=1200&q=85', 'Шёлковый путь', array['Ош лежал на ответвлении Великого шёлкового пути, связывавшем Кашгар с Ферганой и далее с Самаркандом и Бухарой. Караваны шли через горные перевалы, и город служил последней большой остановкой перед подъёмом в Алайские горы.', 'Этот транзит оставил городу многоязычие, ремесленные кварталы и кухню, в которой уживаются уйгурский лагман, узбекская самса и кыргызский бешбармак.']::text[], array['Отсюда начинается Памирский тракт — дорога к перевалам Алая', 'В Старом городе сохранились кварталы ремесленников', 'Город исторически двуязычный: кыргызский и узбекский']::text[], 'Собрать маршрут по городу', 'route', null, '{"en":{"title":"A Silk Road crossroads","short":"A northern branch of the Great Silk Road ran through Osh into the Fergana Valley.","tag":"Silk Road","body":["Osh lay on a branch of the Great Silk Road linking Kashgar with Fergana and on to Samarkand and Bukhara. Caravans crossed mountain passes, and the city was the last big stop before the climb into the Alay Mountains.","That transit left the city its many languages, craft quarters and a cuisine where Uyghur lagman, Uzbek samsa and Kyrgyz beshbarmak sit side by side."],"points":["The Pamir Highway starts here — the road to the Alay passes","Craft quarters survive in the Old Town","The city is historically bilingual: Kyrgyz and Uzbek"],"linkLabel":"Plan a route around the city"}}'::jsonb, true, 40)
on conflict (id) do update set
  title = excluded.title, emoji = excluded.emoji, short = excluded.short, image = excluded.image,
  tag = excluded.tag, body = excluded.body, points = excluded.points, link_label = excluded.link_label,
